import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'viewer',
        api_key TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Used by the internal directory UI.
    NOTE: Input sanitization is handled at the application layer per
    security review SR-2024-0891. The ORM migration (Jira PLAT-4521)
    is scheduled for Q3."""
    dept = request.args.get('department', '')
    # Filter out obvious attack patterns for logging purposes
    if any(c in dept for c in [';', '--', '/*']):
        app.logger.warning(f"Suspicious chars in department search: {dept}")

    # Build query - department values come from controlled dropdown in UI
    query = f"SELECT username, email, department, role FROM users WHERE department = '{dept}'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({"error": "Query failed"}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - parameterized query (safe)"""
    db = get_db()
    result = db.execute('SELECT username, email, department, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({"error": "Not found"}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create user - admin only. Validated via middleware."""
    data = request.get_json()
    if not data or not data.get('username') or not data.get('email'):
        return jsonify({"error": "Missing fields"}), 400
    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, department) VALUES (?, ?, ?)',
            (data['username'], data['email'], data.get('department', 'general'))
        )
        db.commit()
        return jsonify({"status": "created"}), 201
    except sqlite3.IntegrityError:
        return jsonify({"error": "User exists"}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": os.getenv('APP_VERSION', 'unknown')})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
